//! Conformance suite for the Graven v1 wire format: the frozen test vectors
//! ([`vectors`]), the conformance schemas described as data ([`model`]) and the code
//! `gravenc` generates for them ([`generated`]).
//!
//! The schema-driven interpreter lives in `graven-dynamic` and is re-exported here.
pub use graven_dynamic::interp;
pub mod model;

/// Code generated by `gravenc` for `schemas/conformance.graven` (via `build.rs`), checked
/// against the frozen vectors in `tests/generated.rs`.
///
/// The verified view cannot be constructed outside the generated module:
/// ```compile_fail,E0603
/// let buf = [0u8; 128];
/// let t = graven_conformance::generated::Root::read(&buf).unwrap();
/// let v = graven_conformance::generated::RootVerified(t);
/// ```
#[deny(unsafe_code)]
pub mod generated {
    include!(concat!(env!("OUT_DIR"), "/conformance.rs"));
}
pub mod rpc_vectors;
pub mod vectors;

pub use interp::{Value, field_kind, layout, read, write};
pub use model::*;
